// Reading the design libraries' gallery pages (design/generals/gallery.html, design/units/<nation>/unit-cards.html):
// which painting is current for each commander and regiment. Pure: tools/build-history-data.ts does the file work.
// The pages are generated by the image pipeline, one entry per line or element; these read only what they need.

/** A commander's portrait as the gallery lists it: its path under design/generals/, name and role. */
export interface GalleryPortrait {
  src: string
  name: string
  role: string
}

/** A regiment's card as its army's unit-cards page lists it: the card's slug ("13-cuirassier"), title, image file. */
export interface UnitCard {
  slug: string
  title: string
  src: string
}

const ENTITIES: Record<string, string> = { '&amp;': '&', '&#39;': "'", '&quot;': '"', '&lt;': '<', '&gt;': '>' }

/** `text` with the HTML entities the generated pages use decoded. */
export function decodeEntities(text: string): string {
  return text.replace(/&(amp|#39|quot|lt|gt);/g, m => ENTITIES[m] ?? m)
}

/** The first group of `pattern` in `block`; throws, naming `what`, when it is missing (a page the parser no longer
 *  reads right must fail, not drop an entry or take its neighbour's field). */
function field(block: string, pattern: RegExp, what: string): string {
  const found = block.match(pattern)?.[1]
  if (found === undefined) throw new Error(`history sources: no ${what} in ${block.slice(0, 80).replace(/\s+/g, ' ')}`)
  return found
}

/** The portraits in design/generals/gallery.html, in page order: each `<figure>`, read within itself. */
export function parseGallery(html: string): GalleryPortrait[] {
  return [...html.matchAll(/<figure\b[^>]*>(.*?)<\/figure>/gs)].map(([, block]) => ({
    src: field(block, /<a\s+href="([^"]+)"/, 'portrait link'),
    name: decodeEntities(field(block, /<b>([^<]+)<\/b>/, 'name')).trim(),
    role: decodeEntities(field(block, /<\/b>\s*<br>\s*([^<]+?)\s*<br>/, 'role')).trim(),
  }))
}

/** The cards in a design/units/<nation>/unit-cards.html, in page order: each `<article>`, read within itself. The
 *  heading is "<slug> — <title>". */
export function parseUnitCards(html: string): UnitCard[] {
  return [...html.matchAll(/<article\s+id="([^"]+)"[^>]*>(.*?)<\/article>/gs)].map(([, slug, block]) => ({
    slug,
    title: titleOfHeading(slug, decodeEntities(field(block, /<h2>([^<]*)<\/h2>/, `heading of ${slug}`)).trim()),
    src: field(block, /<img\b[^>]*?\ssrc="([^"]+)"/, `image of ${slug}`),
  }))
}

function titleOfHeading(slug: string, heading: string): string {
  const prefix = `${slug} — `
  return heading.startsWith(prefix) ? heading.slice(prefix.length) : heading
}

/** A card title "Name — detail — more" split at its first dash: { name, detail: "detail — more" }. */
export function splitTitle(title: string): { name: string; detail: string } {
  const [name, ...rest] = title.split(' — ')
  return { name: name.trim(), detail: rest.join(' — ').trim() }
}

/** The arm of the first rule whose pattern matches `slug` (its number dropped), else `fallback`. */
export function armOfSlug(slug: string, rules: readonly [string, RegExp][], fallback: string): string {
  const bare = slug.replace(/^\d+-/, '')
  return rules.find(([, pattern]) => pattern.test(bare))?.[0] ?? fallback
}

/** A portrait file's person id: "french/jean_lannes-portrait-oil-v12.png" → "jean_lannes", in plain ASCII. */
export function personIdOf(src: string): string {
  const file = src.split('/').pop() ?? src
  return asciiId(file.replace(/-portrait.*$|\.png$/g, ''))
}

/** `text` lower-cased, accents dropped, anything but letters, digits, `_` and `-` turned to `_`. */
export function asciiId(text: string): string {
  return text
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/ł/g, 'l')
    .replace(/[^a-z0-9_-]/g, '_')
}
